impl FromJs for rune::DragOperation {
    fn from_js(v: conv::Value) -> conv::Result<Self> {
        let (tag, payload) = conv::enum_tag(v, "DragOperation")?;
        match (tag.as_str(), payload) {
            ("Copy", _) => Ok(rune::DragOperation::Copy),
            ("Move", _) => Ok(rune::DragOperation::Move),
            ("Link", _) => Ok(rune::DragOperation::Link),
            (other, _) => Err(conv::err(format!("{other:?} isn't a {} variant (or lacks its value)", "DragOperation"))),
        }
    }
}
impl ToJs for rune::DragOperation {
    fn to_js(self) -> conv::Result<conv::Value> {
        #[allow(unreachable_patterns)]
        match self {
            rune::DragOperation::Copy => conv::ToJs::to_js("Copy"),
            rune::DragOperation::Move => conv::ToJs::to_js("Move"),
            rune::DragOperation::Link => conv::ToJs::to_js("Link"),
            _ => Ok(conv::undefined()),
        }
    }
}

