impl FromJs for rune::Stage {
    fn from_js(v: conv::Value) -> conv::Result<Self> {
        let (tag, payload) = conv::enum_tag(v, "Stage")?;
        match (tag.as_str(), payload) {
            ("Center", _) => Ok(rune::Stage::Center),
            ("Scroll", _) => Ok(rune::Stage::Scroll),
            ("Fill", _) => Ok(rune::Stage::Fill),
            (other, _) => Err(conv::err(format!("{other:?} isn't a {} variant (or lacks its value)", "Stage"))),
        }
    }
}
impl ToJs for rune::Stage {
    fn to_js(self) -> conv::Result<conv::Value> {
        #[allow(unreachable_patterns)]
        match self {
            rune::Stage::Center => conv::ToJs::to_js("Center"),
            rune::Stage::Scroll => conv::ToJs::to_js("Scroll"),
            rune::Stage::Fill => conv::ToJs::to_js("Fill"),
            _ => Ok(conv::undefined()),
        }
    }
}

/// A story with its own state, made by `init` when it first shows and kept, timers and
/// animations included, until the playground closes. R makes it again. Handlers built for `P`
/// change it.
///
/// ```ignore
/// Story::new("Progress/Upload", Upload::new, upload_view)
///     .poll(Upload::tick)
///     .trigger('r', "Run", |u, play| play.after(0.5, |u, _| u.done = true))
///     .trigger('f', "Finish", |u, _| u.done = true)
