impl Class for W_Story {
    type Inner = rune::Story<crate::state::JsState>;
    const NAME: &'static str = "Story";
    fn wrap(slot: conv::Slot<Self::Inner>) -> Self {
        W_Story { slot }
    }
    fn slot(&mut self) -> &mut conv::Slot<Self::Inner> {
        &mut self.slot
    }
}
impl FromJs for rune::Story<crate::state::JsState> {
    fn from_js(v: conv::Value) -> conv::Result<Self> {
        conv::take::<W_Story>(v)
    }
}
impl ToJs for rune::Story<crate::state::JsState> {
    fn to_js(self) -> conv::Result<conv::Value> {
        conv::owned::<W_Story>(self)
    }
}
