impl FromJs for rune::LineCap {
    fn from_js(v: conv::Value) -> conv::Result<Self> {
        let (tag, payload) = conv::enum_tag(v, "LineCap")?;
        match (tag.as_str(), payload) {
            ("Butt", _) => Ok(rune::LineCap::Butt),
            ("Round", _) => Ok(rune::LineCap::Round),
            (other, _) => Err(conv::err(format!("{other:?} isn't a {} variant (or lacks its value)", "LineCap"))),
        }
    }
}
impl ToJs for rune::LineCap {
    fn to_js(self) -> conv::Result<conv::Value> {
        #[allow(unreachable_patterns)]
        match self {
            rune::LineCap::Butt => conv::ToJs::to_js("Butt"),
            rune::LineCap::Round => conv::ToJs::to_js("Round"),
            _ => Ok(conv::undefined()),
        }
    }
}

