impl FromJs for rune::Family {
    fn from_js(v: conv::Value) -> conv::Result<Self> {
        let (tag, payload) = conv::enum_tag(v, "Family")?;
        match (tag.as_str(), payload) {
            ("Sans", _) => Ok(rune::Family::Sans),
            ("Mono", _) => Ok(rune::Family::Mono),
            ("Named", Some(p)) => Ok(rune::Family::Named(conv::arg::<&'static str>(p, "Family.Named")?)),
            ("SystemMono", _) => Ok(rune::Family::SystemMono),
            (other, _) => Err(conv::err(format!("{other:?} isn't a {} variant (or lacks its value)", "Family"))),
        }
    }
}
impl ToJs for rune::Family {
    fn to_js(self) -> conv::Result<conv::Value> {
        #[allow(unreachable_patterns)]
        match self {
            rune::Family::Sans => conv::ToJs::to_js("Sans"),
            rune::Family::Mono => conv::ToJs::to_js("Mono"),
            rune::Family::Named(a) => Ok(conv::tagged("Named", a.to_js()?)),
            rune::Family::SystemMono => conv::ToJs::to_js("SystemMono"),
            _ => Ok(conv::undefined()),
        }
    }
}

