impl FromJs for rune::PopupMenuError {
    fn from_js(v: conv::Value) -> conv::Result<Self> {
        let (tag, payload) = conv::enum_tag(v, "PopupMenuError")?;
        match (tag.as_str(), payload) {
            ("NotOpen", _) => Ok(rune::PopupMenuError::NotOpen),
            ("UnknownItem", Some(p)) => Ok(rune::PopupMenuError::UnknownItem(conv::arg::<String>(p, "PopupMenuError.UnknownItem")?)),
            ("Disabled", Some(p)) => Ok(rune::PopupMenuError::Disabled(conv::arg::<String>(p, "PopupMenuError.Disabled")?)),
            (other, _) => Err(conv::err(format!("{other:?} isn't a {} variant (or lacks its value)", "PopupMenuError"))),
        }
    }
}
impl ToJs for rune::PopupMenuError {
    fn to_js(self) -> conv::Result<conv::Value> {
        #[allow(unreachable_patterns)]
        match self {
            rune::PopupMenuError::NotOpen => conv::ToJs::to_js("NotOpen"),
            rune::PopupMenuError::UnknownItem(a) => Ok(conv::tagged("UnknownItem", a.to_js()?)),
            rune::PopupMenuError::Disabled(a) => Ok(conv::tagged("Disabled", a.to_js()?)),
            _ => Ok(conv::undefined()),
        }
    }
}

