impl FromJs for rune::PlayerState {
    fn from_js(v: conv::Value) -> conv::Result<Self> {
        let (tag, payload) = conv::enum_tag(v, "PlayerState")?;
        match (tag.as_str(), payload) {
            ("Loading", _) => Ok(rune::PlayerState::Loading),
            ("Ready", _) => Ok(rune::PlayerState::Ready),
            ("Playing", _) => Ok(rune::PlayerState::Playing),
            ("Ended", _) => Ok(rune::PlayerState::Ended),
            ("Failed", Some(p)) => Ok(rune::PlayerState::Failed(conv::arg::<String>(p, "PlayerState.Failed")?)),
            (other, _) => Err(conv::err(format!("{other:?} isn't a {} variant (or lacks its value)", "PlayerState"))),
        }
    }
}
impl ToJs for rune::PlayerState {
    fn to_js(self) -> conv::Result<conv::Value> {
        #[allow(unreachable_patterns)]
        match self {
            rune::PlayerState::Loading => conv::ToJs::to_js("Loading"),
            rune::PlayerState::Ready => conv::ToJs::to_js("Ready"),
            rune::PlayerState::Playing => conv::ToJs::to_js("Playing"),
            rune::PlayerState::Ended => conv::ToJs::to_js("Ended"),
            rune::PlayerState::Failed(a) => Ok(conv::tagged("Failed", a.to_js()?)),
            _ => Ok(conv::undefined()),
        }
    }
}

